/* @lc app=leetcode id=1562 lang=kotlin */
class Solution { fun findLatestStep(arr: IntArray, m: Int): Int = arr.indices.fold(IntArray(arr.size + 2) to (0 to -1)) { (l, state), i -> arr[i].let { x -> l[x - 1].let { left -> l[x + 1].let { right -> (left + right + 1).let { newLen -> l.also { it[x - left] = newLen }.also { it[x + right] = newLen }.let { (state.first - (if (left == m) 1 else 0) - (if (right == m) 1 else 0) + (if (newLen == m) 1 else 0)).let { count -> l to (count to (if (count > 0) i + 1 else state.second)) } } } } } } }.second.second }